record.field:
for record in records:
    if record.product_template_id:
        services = env['product.package.service'].search([('product_template_id', '=', record.product_template_id.id)])
        product_ids = services.mapped('product_id').ids
        record.write({'service_ids': [(6, 0, product_ids)] if product_ids else [(6, 0, [])]})
    else:
        record.write({'service_ids': [(6, 0, [])]})
